using Microsoft.EntityFrameworkCore; using Microsoft.OpenApi.Models; using RaceDay.Api.Data; using RaceDay.Api.Services;
	var builder=WebApplication.CreateBuilder(args);builder.Services.AddControllers();builder.Services.AddHttpContextAccessor();builder.Services.AddDistributedMemoryCache();builder.Services.AddSession(o=>{o.Cookie.HttpOnly=true;o.Cookie.IsEssential=true;o.IdleTimeout=TimeSpan.FromHours(8);});builder.Services.AddDbContext<RaceDayDbContext>(o=>o.UseSqlServer(builder.Configuration.GetConnectionString("DefaultConnection")));builder.Services.AddScoped<IPasswordService,PasswordService>();builder.Services.AddScoped<SessionAuth>();builder.Services.AddScoped<IBlobStorageService,BlobStorageService>();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen(c=>c.SwaggerDoc("v1",new OpenApiInfo{Title="RaceDay API",Version="v1",Description="Session-authenticated API for organisers and participants."}));var app=builder.Build();if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();}app.UseHttpsRedirection();app.UseStaticFiles();app.UseSession();app.MapControllers();app.Run();public partial class Program{}
